/* Mandatory display override for hidden elements */
[hidden] {
  display: none !important;
}

:root {
  --bg-city: #1e2029;
  --meter-metal: #59616e;
  --meter-metal-dark: #3b424d;
  --meter-metal-light: #7b8493;
  --screen-idle-bg: #8ba888;
  --screen-idle-fg: #152417;
  --screen-expired-bg: #c93b3b;
  --screen-expired-fg: #fff3f3;
  --btn-gold: #e2a83b;
  --btn-gold-border: #9b6c16;
  --btn-gold-shadow: #634305;
  --btn-reset: #6c757d;
  --btn-reset-border: #444a50;
  --btn-reset-shadow: #26292d;
  --pixel-border: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-city);
  background-image: 
    radial-gradient(#2b2f3d 15%, transparent 16%),
    radial-gradient(#262a36 15%, transparent 16%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: "Courier New", Courier, monospace, system-ui;
  padding: 24px 16px;
  color: #fff;
}

.meter-container {
  width: 100%;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.meter-cap {
  background: var(--meter-metal-dark);
  border: var(--pixel-border) solid #111;
  border-bottom: none;
  width: 240px;
  padding: 12px 8px 8px;
  text-align: center;
  box-shadow: inset 0 4px 0 var(--meter-metal-light);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.meter-signal {
  width: 16px;
  height: 16px;
  background: #393e46;
  border: 2px solid #111;
  box-shadow: inset 1px 1px 0 #6c757d;
}

.meter-signal.active {
  background: #4ade80;
  box-shadow: 0 0 8px #4ade80;
}

.meter-signal.expired {
  background: #ef4444;
  box-shadow: 0 0 8px #ef4444;
}

.meter-title {
  font-size: 16px;
  letter-spacing: 2px;
  color: #d1d5db;
  font-weight: 800;
  text-shadow: 1px 1px 0 #000;
}

.meter-housing {
  width: 100%;
  background: var(--meter-metal);
  border: var(--pixel-border) solid #111;
  padding: 24px 20px;
  box-shadow:
    inset var(--pixel-border) var(--pixel-border) 0 var(--meter-metal-light),
    inset calc(var(--pixel-border) * -1) calc(var(--pixel-border) * -1) 0 var(--meter-metal-dark),
    0 12px 24px rgba(0, 0, 0, 0.45);
}

.screen-frame {
  background: #23272e;
  border: var(--pixel-border) solid #111;
  padding: 12px;
  margin-bottom: 24px;
  box-shadow: inset 2px 2px 0 rgba(0, 0, 0, 0.6);
}

.screen {
  position: relative;
  background: var(--screen-idle-bg);
  color: var(--screen-idle-fg);
  padding: 18px 12px;
  border: 2px solid #181d19;
  min-height: 130px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  transition: background-color 0.15s steps(2), color 0.15s steps(2);
  overflow: hidden;
}

.screen-scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.08) 0px,
    rgba(0, 0, 0, 0.08) 2px,
    transparent 2px,
    transparent 4px
  );
}

.screen-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  opacity: 0.8;
  margin-bottom: 6px;
}

.time-display {
  font-size: 40px;
  font-weight: 900;
  letter-spacing: 2px;
  line-height: 1;
  margin: 4px 0;
  font-variant-numeric: tabular-nums;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.2);
}

.expired-banner {
  font-size: 30px;
  font-weight: 900;
  letter-spacing: 3px;
  margin: 6px 0;
  animation: pulse-pixel 1s infinite alternate steps(2);
}

.instruction-text {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  opacity: 0.85;
  text-transform: uppercase;
}

/* Screen Expired State */
.screen.expired {
  background-color: var(--screen-expired-bg);
  color: var(--screen-expired-fg);
}

@keyframes pulse-pixel {
  0% { transform: scale(1); }
  100% { transform: scale(1.05); }
}

/* Button Controls */
.controls-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.button-row {
  display: flex;
  gap: 12px;
}

.pixel-btn {
  flex: 1;
  font-family: inherit;
  font-size: 16px;
  font-weight: 800;
  padding: 14px 10px;
  cursor: pointer;
  border: var(--pixel-border) solid #111;
  user-select: none;
  outline: none;
  position: relative;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.pixel-btn:focus-visible {
  outline: 3px dashed #fff;
  outline-offset: 3px;
}

.btn-add {
  background: var(--btn-gold);
  color: #2b1f03;
  box-shadow:
    inset var(--pixel-border) var(--pixel-border) 0 #fed876,
    inset calc(var(--pixel-border) * -1) calc(var(--pixel-border) * -1) 0 var(--btn-gold-shadow),
    0 4px 0 #111;
}

.btn-add:hover {
  background: #f0b54a;
}

.btn-add:active {
  transform: translateY(4px);
  box-shadow:
    inset var(--pixel-border) var(--pixel-border) 0 #fed876,
    inset calc(var(--pixel-border) * -1) calc(var(--pixel-border) * -1) 0 var(--btn-gold-shadow),
    0 0 0 #111;
}

.btn-reset {
  background: var(--btn-reset);
  color: #f8fafc;
  box-shadow:
    inset var(--pixel-border) var(--pixel-border) 0 #9ca3af,
    inset calc(var(--pixel-border) * -1) calc(var(--pixel-border) * -1) 0 var(--btn-reset-shadow),
    0 4px 0 #111;
}

.btn-reset:hover {
  background: #7a848e;
}

.btn-reset:active {
  transform: translateY(4px);
  box-shadow:
    inset var(--pixel-border) var(--pixel-border) 0 #9ca3af,
    inset calc(var(--pixel-border) * -1) calc(var(--pixel-border) * -1) 0 var(--btn-reset-shadow),
    0 0 0 #111;
}

/* Bottom Pole Graphics */
.meter-pole {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}

.pole-ring {
  width: 90px;
  height: 14px;
  background: var(--meter-metal-dark);
  border: var(--pixel-border) solid #111;
  border-top: none;
}

.pole-shaft {
  width: 48px;
  height: 48px;
  background: repeating-linear-gradient(
    90deg,
    #2c323b 0px,
    #3f4753 12px,
    #2c323b 24px
  );
  border-left: var(--pixel-border) solid #111;
  border-right: var(--pixel-border) solid #111;
}

@media (max-width: 360px) {
  .time-display {
    font-size: 32px;
  }

  .pixel-btn {
    font-size: 14px;
    padding: 12px 6px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let remainingSeconds = 0;
  let timerInterval = null;
  let hasStarted = false;

  const timeDisplay = document.getElementById('timeDisplay');
  const expiredBanner = document.getElementById('expiredBanner');
  const instructionText = document.getElementById('instructionText');
  const meterScreen = document.getElementById('meterScreen');
  const meterSignal = document.getElementById('meterSignal');
  const btnAdd15 = document.getElementById('btnAdd15');
  const btnAdd60 = document.getElementById('btnAdd60');
  const btnReset = document.getElementById('btnReset');

  function formatTime(totalSeconds) {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    const paddedMinutes = String(minutes).padStart(2, '0');
    const paddedSeconds = String(seconds).padStart(2, '0');

    return `${hours}:${paddedMinutes}:${paddedSeconds}`;
  }

  function setExpiredState() {
    stopTimer();
    remainingSeconds = 0;
    timeDisplay.textContent = '0:00:00';
    timeDisplay.hidden = true;
    expiredBanner.hidden = false;
    instructionText.textContent = 'TIME EXPIRED';
    meterScreen.classList.add('expired');
    meterSignal.className = 'meter-signal expired';
  }

  function setIdleState() {
    stopTimer();
    remainingSeconds = 0;
    hasStarted = false;
    timeDisplay.textContent = '0:00:00';
    timeDisplay.hidden = false;
    expiredBanner.hidden = true;
    instructionText.textContent = 'INSERT TIME';
    meterScreen.classList.remove('expired');
    meterSignal.className = 'meter-signal';
  }

  function setActiveState() {
    timeDisplay.hidden = false;
    expiredBanner.hidden = true;
    instructionText.textContent = 'ACTIVE METER';
    meterScreen.classList.remove('expired');
    meterSignal.className = 'meter-signal active';
    timeDisplay.textContent = formatTime(remainingSeconds);
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
      timeDisplay.textContent = formatTime(remainingSeconds);
      if (remainingSeconds === 0) {
        setExpiredState();
      }
    } else {
      setExpiredState();
    }
  }

  function startTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
    }
    timerInterval = setInterval(tick, 1000);
  }

  function stopTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function addTime(seconds) {
    remainingSeconds += seconds;
    hasStarted = true;
    setActiveState();
    startTimer();
  }

  // Event Listeners
  btnAdd15.addEventListener('click', () => {
    addTime(15 * 60);
  });

  btnAdd60.addEventListener('click', () => {
    addTime(60 * 60);
  });

  btnReset.addEventListener('click', () => {
    setIdleState();
  });

  // Keyboard Accessibility: Numeric shortcuts '1' for 15m, '2' for 1h, 'r' for reset
  window.addEventListener('keydown', (e) => {
    if (e.target && ['input', 'textarea'].includes(e.target.tagName.toLowerCase())) {
      return;
    }
    if (e.key === '1') {
      addTime(15 * 60);
    } else if (e.key === '2') {
      addTime(60 * 60);
    } else if (e.key === 'r' || e.key === 'R') {
      setIdleState();
    }
  });

  // Initialize in idle state
  setIdleState();
});
